"""Edge-case tests for composition-facet — generated by bug-hunter agent."""
from __future__ import annotations

import json
import pytest
import polars as pl
import ferrum as fr
from ferrum import Chart
from ferrum.composition import HConcatChart, VConcatChart, JointChart, RepeatChart


# ---------------------------------------------------------------------------
# HConcat / VConcat edge cases
# ---------------------------------------------------------------------------


def test_hconcat_single_chart_svg_is_valid():
    """HConcatChart with exactly one chart should render without error."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c = Chart(df).mark_point().encode(x="x", y="y")
    combined = HConcatChart([c])
    svg = combined.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")
    assert "NaN" not in svg


def test_vconcat_single_chart_svg_is_valid():
    """VConcatChart with exactly one chart should render without error."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c = Chart(df).mark_point().encode(x="x", y="y")
    combined = VConcatChart([c])
    svg = combined.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")
    assert "NaN" not in svg


def test_hconcat_many_charts_renders():
    """HConcatChart with 5+ charts renders without NaN in output."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    charts = [Chart(df).mark_point().encode(x="x", y="y") for _ in range(5)]
    combined = HConcatChart(charts)
    svg = combined.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")
    assert "NaN" not in svg
    # Each chart should produce at least one translate wrapper
    assert svg.count('transform="translate(') >= 5


def test_hconcat_no_viewbox_nan():
    """Composed SVG viewBox must not contain NaN."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    svg = (c1 | c2).show_svg()
    # Extract viewBox if present and check it doesn't have NaN values
    if 'viewBox="' in svg:
        idx = svg.index('viewBox="') + 9
        end = svg.index('"', idx)
        viewbox_val = svg[idx:end]
        assert "nan" not in viewbox_val.lower()
        assert "NaN" not in viewbox_val


def test_hconcat_custom_spacing_renders():
    """HConcatChart with non-default spacing renders without error."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_point().encode(x="x", y="y")
    combined = HConcatChart([c1, c2], spacing=50.0)
    svg = combined.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")


def test_vconcat_custom_spacing_renders():
    """VConcatChart with non-default spacing renders without error."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_point().encode(x="x", y="y")
