def test_hconcat_repr_is_descriptive():
    """HConcatChart repr should mention chart count."""
    df = pl.DataFrame({"x": [1], "y": [2]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_line().encode(x="x", y="y")
    result = c1 | c2
    r = repr(result)
    assert "HConcatChart" in r


def test_vconcat_repr_is_descriptive():
    """VConcatChart repr should mention VConcatChart."""
    df = pl.DataFrame({"x": [1], "y": [2]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    result = c1 & c2
    r = repr(result)
    assert "VConcatChart" in r


def test_rebuild_with_charts_returns_same_type():
    """_rebuild_with_charts on HConcat/VConcat preserves composition type."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    h = c1 | c2
    rebuilt = h._rebuild_with_charts(lambda c: c)
    assert isinstance(rebuilt, HConcatChart)
    assert len(rebuilt.charts) == 2

    v = c1 & c2
    rebuilt_v = v._rebuild_with_charts(lambda c: c)
    assert isinstance(rebuilt_v, VConcatChart)
    assert len(rebuilt_v.charts) == 2


def test_share_scale_invalid_mode_raises_value_error():
    """share_scale with invalid mode raises ValueError with legible message."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    with pytest.raises(ValueError, match="shared.*independent|independent.*shared"):
        combined.share_scale(x="together")  # invalid mode


def test_share_scale_independent_is_noop():
    """share_scale with all-independent channels returns self."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    result = combined.share_scale(x="independent", y="independent")
    assert result is combined


