def test_joint_chart_zero_ratio_raises():
    """JointChart with ratio=0 raises ValueError."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match="ratio"):
        JointChart(center, ratio=0)


def test_joint_chart_negative_ratio_raises():
    """JointChart with negative ratio raises ValueError."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    with pytest.raises(ValueError, match="ratio"):
        JointChart(center, ratio=-1)


def test_joint_chart_center_only_renders():
    """JointChart with only center (no marginals) renders valid SVG."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    joint = JointChart(center)
    svg = joint.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")
    assert "NaN" not in svg


def test_joint_chart_with_marginals_renders():  # BUG: ValueError: stat_bin: column 'x' must be Float64; got Int64 — mark_histogram on Int64 marginal column fails in JointChart
    """JointChart with top and right marginals renders valid SVG."""
    df = pl.DataFrame({"x": [1, 2, 3, 4, 5], "y": [6, 7, 8, 9, 10]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    top = Chart(df).mark_histogram().encode(x="x")
    right = Chart(df).mark_histogram().encode(x="y")
    joint = JointChart(center, top=top, right=right)
    svg = joint.show_svg()
    assert svg.startswith("<svg") or svg.startswith("<?xml")
    assert "NaN" not in svg


def test_joint_chart_charts_property():
    """JointChart.charts includes all non-None sub-charts."""
    df = pl.DataFrame({"x": [1], "y": [2]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    top = Chart(df).mark_histogram().encode(x="x")
    joint = JointChart(center, top=top)
    assert len(joint.charts) == 2
    joint_no_top = JointChart(center)
    assert len(joint_no_top.charts) == 1


def test_joint_chart_spec_contains_kind():
    """JointChart.spec emits kind='joint'."""
    df = pl.DataFrame({"x": [1], "y": [2]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    joint = JointChart(center)
    spec = joint.spec
    assert spec["kind"] == "joint"
    assert spec["ratio"] > 0


def test_joint_chart_rebuild_with_charts():
    """_rebuild_with_charts on JointChart returns a JointChart."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    center = Chart(df).mark_point().encode(x="x", y="y")
    top = Chart(df).mark_histogram().encode(x="x")
    joint = JointChart(center, top=top, ratio=4)
    rebuilt = joint._rebuild_with_charts(lambda c: c)
    assert isinstance(rebuilt, JointChart)
    assert rebuilt.ratio == 4


