def test_facet_single_panel_renders():
    """A faceted chart where the facet column has only 1 unique value renders cleanly."""
    import pyarrow as pa
    from ferrum._core import render_svg

    tbl = pa.table({
        "x": pa.array([1, 2, 3], type=pa.int64()),
        "y": pa.array([4, 5, 6], type=pa.int64()),
        "grp": pa.array(["A", "A", "A"], type=pa.string()),
    })
    df = pl.from_arrow(tbl)
    chart = Chart(df).mark_point().encode(x="x", y="y").facet(col="grp")
    spec = chart.to_spec()
    svg = render_svg(spec, tbl, viewport=(600.0, 400.0), theme={})
    assert "NaN" not in svg
    # Should have at least one text element for the strip title "A"
    assert "<text" in svg


def test_facet_grid_mode_spec_round_trip():  # BUG: KeyError 'row' — grid mode facet spec silently drops the row field; only col is preserved as 'field'
    """facet(row=, col=) round-trips through JSON with kind='grid'."""
    df = pl.DataFrame({
        "x": [1, 2], "y": [3, 4],
        "r": ["r1", "r2"], "c": ["c1", "c2"]
    })
    chart = Chart(df).mark_point().encode(x="x", y="y").facet(row="r", col="c")
    spec_json = json.loads(chart.to_spec().to_json())
    facet = spec_json.get("facet")
    assert facet is not None
    assert facet["mode"]["kind"] == "grid"
    assert facet["row"] == "r"


def test_facet_ncols_wires_to_spec():
    """facet(field=, ncols=N) wires ncols into the spec JSON."""
    df = pl.DataFrame({"x": [1, 2, 3], "g": ["A", "B", "C"]})
    chart = Chart(df).mark_point().encode(x="x", y="x").facet(field="g", ncols=3)
    spec_json = json.loads(chart.to_spec().to_json())
    facet = spec_json.get("facet")
    assert facet is not None
    assert facet["mode"]["ncols"] == 3


def test_facet_no_args_raises_value_error():
    """facet() with no args raises ValueError with 'facet' in message."""
    df = pl.DataFrame({"x": [1]})
    chart = Chart(df).mark_point().encode(x="x", y="x")
    with pytest.raises(ValueError, match="facet"):
        chart.facet()


def test_facet_col_only_is_wrap_mode():
    """facet(col='g') produces wrap mode with field='g'."""
    df = pl.DataFrame({"x": [1, 2], "g": ["A", "B"]})
    chart = Chart(df).mark_point().encode(x="x", y="x").facet(col="g")
    assert chart._facet is not None
    assert chart._facet.mode_kind == "wrap"
    assert chart._facet.field == "g"


def test_facet_row_only_is_wrap_mode():
    """facet(row='g') produces wrap mode (row-only is treated as wrap)."""
    df = pl.DataFrame({"x": [1, 2], "g": ["A", "B"]})
    chart = Chart(df).mark_point().encode(x="x", y="x").facet(row="g")
    assert chart._facet is not None
    assert chart._facet.mode_kind == "wrap"


