def test_save_unknown_format_raises():
    """Saving to an unsupported format raises NotImplementedError."""
    import tempfile, os
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    with tempfile.NamedTemporaryFile(suffix=".pdf", delete=False) as f:
        tmp = f.name
    try:
        with pytest.raises(NotImplementedError, match="svg.*png|png.*svg"):
            combined.save(tmp, format="pdf")
    finally:
        os.unlink(tmp)


def test_save_svg_writes_valid_file(tmp_path):
    """save() with .svg extension writes valid SVG file."""
    df = pl.DataFrame({"x": [1, 2, 3], "y": [4, 5, 6]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    out = tmp_path / "test.svg"
    combined.save(str(out))
    content = out.read_text(encoding="utf-8")
    assert "<svg" in content
    assert "NaN" not in content


def test_mime_bundle_contains_svg():
    """_repr_mimebundle_ includes 'image/svg+xml' key."""
    df = pl.DataFrame({"x": [1, 2], "y": [3, 4]})
    c1 = Chart(df).mark_point().encode(x="x", y="y")
    c2 = Chart(df).mark_bar().encode(x="x", y="y")
    combined = c1 | c2
    bundle = combined._repr_mimebundle_()
    assert "image/svg+xml" in bundle
    svg = bundle["image/svg+xml"]
    assert "<svg" in svg or "<?xml" in svg
